CREATE TRIGGER tr1 BEFORE DELETE ON tblname BEGIN SELECT RAISE(IGNORE); END; CREATE TRIGGER tr2 BEFORE DELETE ON tblname BEGIN SELECT RAISE(ROLLBACK,'error message'); END; CREATE TRIGGER tr3 BEFORE DELETE ON tblname BEGIN SELECT RAISE(ABORT,'error message'); END; CREATE TRIGGER tr4 BEFORE DELETE ON tblname BEGIN SELECT RAISE(FAIL,'error message'); END;